# GENERATED by scripts/sync_seasonals.py from grain-seasonal-dashboard/app.py. Do not edit here: change the source app (or the transform) and re-run `python scripts/sync_seasonals.py apply`.
"""Daily futures settlements banked in Snowflake, for the Trends tab's history.

JSA.COST_OF_CARRY.FUTURES_SETTLEMENTS holds every settlement Massive has served since late
2021 (all six markets here, plus spring wheat), topped up each weekday by
cost-of-carry-calculator's settlement job. One query returns what is otherwise about a minute of
per-contract Massive calls, and the two agree to the cent.

Optional by design. It needs USE_SNOWFLAKE and credentials, which the admin portal has and the
standalone app does not, and anything that goes wrong here falls back to Massive: the connector
is imported only when used, so an environment without it simply never gets this far.
"""
from __future__ import annotations

import os
import time

import pandas as pd

SCHEMA = "COST_OF_CARRY"
TABLE = "FUTURES_SETTLEMENTS"

_TRUE = {"1", "true", "yes", "on"}

# After a failure, don't try again for a while: a dead connection can take seconds to give up
# on, and every rerun of the tab would otherwise pay that.
RETRY_AFTER_SECONDS = 600
_last_failure = float("-inf")


def use_snowflake() -> bool:
    return os.environ.get("USE_SNOWFLAKE", "").strip().lower() in _TRUE


def _load_private_key():
    """RSA private key for Snowflake key-pair auth (the account enforces MFA on password
    sign-ins), as DER bytes; None if not configured (falls back to password).
    Source: SNOWFLAKE_PRIVATE_KEY_PATH (.p8 file) or SNOWFLAKE_PRIVATE_KEY (PEM text)."""
    path = (os.environ.get("SNOWFLAKE_PRIVATE_KEY_PATH") or "").strip()
    pem = os.environ.get("SNOWFLAKE_PRIVATE_KEY") or ""
    if not path and not pem.strip():
        return None
    from cryptography.hazmat.primitives import serialization
    data = open(path, "rb").read() if path else pem.replace("\\n", "\n").encode()
    pwd = os.environ.get("SNOWFLAKE_PRIVATE_KEY_PWD") or None
    key = serialization.load_pem_private_key(data, password=pwd.encode() if pwd else None)
    return key.private_bytes(
        encoding=serialization.Encoding.DER,
        format=serialization.PrivateFormat.PKCS8,
        encryption_algorithm=serialization.NoEncryption())


def _connect():
    import snowflake.connector

    kw = dict(
        account=os.environ["SNOWFLAKE_ACCOUNT"],
        user=os.environ["SNOWFLAKE_USER"],
        # `or` rather than a .get default: an unset secret can arrive as "" rather than absent.
        role=os.environ.get("SNOWFLAKE_ROLE") or "ACCOUNTADMIN",
        warehouse=os.environ.get("SNOWFLAKE_WAREHOUSE") or "COMPUTE_WH",
        database=os.environ.get("SNOWFLAKE_DATABASE") or "JSA",
        schema=SCHEMA,
    )
    pkey = _load_private_key()
    if pkey is not None:
        kw["private_key"] = pkey
    else:
        kw["password"] = os.environ["SNOWFLAKE_PASSWORD"]
    return snowflake.connector.connect(**kw)


def read_settlements(product_codes: list[str], first_year: int) -> pd.DataFrame:
    """Banked settlements as product_code / month / year / date / price, for the given markets
    and contract years from `first_year` on."""
    marks = ", ".join(["%s"] * len(product_codes))
    conn = _connect()
    try:
        cur = conn.cursor()
        try:
            cur.execute(
                f"SELECT PRODUCT_CODE, MONTH, YEAR, DATE, SETTLE FROM {SCHEMA}.{TABLE} "
                f"WHERE PRODUCT_CODE IN ({marks}) AND YEAR >= %s "
                f"ORDER BY PRODUCT_CODE, YEAR, MONTH, DATE",
                (*product_codes, int(first_year)),
            )
            rows = cur.fetchall()
        finally:
            cur.close()
    finally:
        conn.close()

    frame = pd.DataFrame(rows, columns=["product_code", "month", "year", "date", "price"])
    frame["date"] = pd.to_datetime(frame["date"])
    frame["year"] = frame["year"].astype(int)
    frame["price"] = frame["price"].astype(float)
    return frame


def load_bank(product_codes: list[str], first_year: int) -> dict[tuple[str, str, int], pd.Series]:
    """{(product_code, month_letter, contract_year): Series(date -> settlement)}.

    Empty when Snowflake is switched off. When it is on but cannot be read this raises, so a
    caller that caches the result doesn't pin an outage for hours."""
    global _last_failure
    if not use_snowflake():
        return {}
    if time.monotonic() - _last_failure < RETRY_AFTER_SECONDS:
        raise RuntimeError("The Snowflake settlement bank failed recently; not retrying yet.")
    try:
        frame = read_settlements(product_codes, first_year)
    except Exception:
        _last_failure = time.monotonic()
        raise

    out: dict[tuple[str, str, int], pd.Series] = {}
    for (code, month, year), group in frame.groupby(["product_code", "month", "year"]):
        series = pd.Series(group["price"].to_numpy(), index=group["date"].dt.date).sort_index()
        out[(code, month, int(year))] = series[~series.index.duplicated(keep="last")]
    return out
